@RestController
@RequestMapping("/api/users")
@Validated
public class UserController {

    @PostMapping
    public ResponseEntity<UserResponse> createUser(@RequestBody @Valid UserRegistrationDto dto) {
        // If validation fails, Spring automatically throws MethodArgumentNotValidException
        UserResponse response = userService.register(dto);
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }
}

public record UserRegistrationDto(
    @NotBlank(message = "Username cannot be blank")
    @Size(min = 3, max = 50, message = "Username must be between 3 and 50 characters")
    String username,

    @Email(message = "Invalid email format")
    @NotNull(message = "Email is required")
    String email,

    @Min(value = 18, message = "User must be at least 18 years old")
    int age
) {}
